import socket
import ssl
from tls_client import make_client_context


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port, verify server certificate and hostname,
    and return the server's greeting bytes up to and including the first newline,
    or until connection closes, max 4096 bytes."""
    if server_hostname is None:
        server_hostname = host
    ctx = make_client_context(cafile)
    with socket.create_connection((host, port)) as sock:
        with ctx.wrap_socket(sock, server_hostname=server_hostname) as tls_sock:
            # Read up to 4096 bytes or until first newline
            data = bytearray()
            while len(data) < 4096:
                chunk = tls_sock.recv(4096 - len(data))
                if not chunk:
                    break
                data.extend(chunk)
                if b"\n" in chunk:
                    break
            # Return up to and including the first newline if present
            newline_index = data.find(b"\n")
            if newline_index != -1:
                return bytes(data[:newline_index + 1])
            else:
                return bytes(data)

import socket
import ssl
from tls_client import wrap_client_socket


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    if server_hostname is None:
        server_hostname = host
    # Create a TCP socket and connect
    sock = socket.create_connection((host, port))
    try:
        # Wrap the socket in TLS with verification
        tls_sock = wrap_client_socket(sock, server_hostname, cafile)
        try:
            # Read up to 4096 bytes or until the first newline (inclusive)
            data = bytearray()
            while len(data) < 4096:
                chunk = tls_sock.recv(4096 - len(data))
                if not chunk:
                    break
                data.extend(chunk)
                if b'\n' in chunk:
                    # Stop at the first newline (inclusive)
                    newline_index = data.find(b'\n') + 1
                    return bytes(data[:newline_index])
            return bytes(data)
        finally:
            tls_sock.close()
    except ssl.SSLError:
        # Reraise SSL errors as required
        raise
    finally:
        sock.close()

import socket
import ssl
from tls_client import wrap_client_socket


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port, verify server cert and hostname, return greeting bytes.

    The greeting is the bytes received up to and including the first newline byte,
    or up to 4096 bytes if no newline is received before connection close.

    Raises ssl.SSLError or ssl.CertificateError on verification failure.
    """
    if server_hostname is None:
        server_hostname = host

    with socket.create_connection((host, port)) as sock:
        tls_sock = wrap_client_socket(sock, server_hostname, cafile)
        # Read up to 4096 bytes or until first newline (b'\n') inclusive.
        buf = bytearray()
        while len(buf) < 4096:
            chunk = tls_sock.recv(4096 - len(buf))
            if not chunk:
                # Connection closed by server
                break
            buf.extend(chunk)
            if b'\n' in chunk:
                # Stop after including first newline
                break
        # Return bytes up to and including first newline, or all if no newline
        newline_index = buf.find(b'\n')
        if newline_index >= 0:
            return bytes(buf[:newline_index + 1])
        else:
            return bytes(buf)
